// This file was generated by Slater.app - Testimonials section.js


gsap.registerPlugin(ScrollTrigger);

const stickyTitle = document.querySelector(".is-avis-title-sticky");

// 1. Animation de base : Position (top) + Opacité
const mainST = gsap.to(stickyTitle, {
  top: "10rem",
  opacity: 0.6, // On descend l'opacité à 60%
  ease: "none",
  scrollTrigger: {
    trigger: ".section_avis",
    start: "top top",
    end: "bottom bottom",
    scrub: 1.5,
    invalidateOnRefresh: true
  }
});

// 2. L'effet de rebond (Bounce) basé sur la vélocité
ScrollTrigger.create({
  trigger: ".section_avis",
  onUpdate: (self) => {
    let velocity = self.getVelocity();

    gsap.to(stickyTitle, {
      y: velocity / 400,
      duration: 0.6,
      ease: "back.out(3)",
      overwrite: "auto"
    });
  }
});


